CREATE OR REPLACE VIEW "RESULT_VIEW"("VALUE", "NVALUE", "NODEID", "BANKID", "PERIODTYPEID", "FROMDATE", "TODATE", "PERIODID", "VERSIONCODE", "LATESTVERSIONCODE") AS SELECT RI.VALUE, RI.NVALUE, RI.NODEID, S.BANKID, P.PERIODTYPEID, P.FROMDATE, P.TODATE, P.ID AS PERIODID, RV.CODE AS VERSIONCODE, RV2.CODE AS LATESTVERSIONCODE FROM IN_SCHEDULES S, IN_PERIODS P, IN_RETURNS R, IN_RETURN_ITEMS RI, IN_RETURN_VERSIONS RV, IN_RETURN_VERSIONS RV2 WHERE S.PERIODID = P.ID AND R.SCHEDULEID=S.ID AND RI.RETURNID=R.ID AND RV.ID = RI.VERSIONID AND RV2.ID = R.VERSIONID;
CREATE OR REPLACE VIEW "RESULT_VIEW_FULL" ("VALUE", "NVALUE", "NODEID", "BANKID", "PERIODTYPEID", "FROMDATE", "TODATE", "PERIODID", "VERSIONID", "LATESTVERSIONID", "RETURNID", "RETURNITEMID", "ITEMTABLEID", "ITEMROWNUMBER", "RDID") AS SELECT RI.VALUE, RI.NVALUE, RI.NODEID, S.BANKID, P.PERIODTYPEID, P.FROMDATE, P.TODATE, P.ID AS PERIODID, RV.ID AS VERSIONID, RV2.id AS LATESTVERSIONID, R.id AS RETURNID, RI.id AS RETURNITEMID, RI.TABLEID AS ITEMTABLEID, RI.ROWNUMBER AS ITEMROWNUMBER, RD.ID AS RDID FROM IN_SCHEDULES S, IN_PERIODS P, IN_RETURNS R, IN_RETURN_ITEMS RI, IN_RETURN_VERSIONS RV, IN_RETURN_VERSIONS RV2, IN_RETURN_DEFINITIONS RD WHERE S.PERIODID = P.ID AND R.SCHEDULEID=S.ID AND RI.RETURNID=R.ID AND RV.ID = R.VERSIONID AND RV2.ID = R.VERSION AND rd.id=s.definitionid;
commit;